  --popover-foreground: oklch(33.54% 0.0145 24.66);
  --primary: oklch(57.42% 0.234 27.99);
  --primary-foreground: oklch(100% 0 0);
  --secondary: oklch(95.28% 0.0144 28.01);
  --secondary-foreground: oklch(33.54% 0.0145 24.66);
  --muted: oklch(95.28% 0.0144 28.01);
  --muted-foreground: oklch(48.47% 0.0147 29.95);
  --accent: oklch(95.3% 0.0233 27.34);
  --accent-foreground: oklch(35.13% 0.1436 27.98);
