  --chart-1: oklch(57.09% 0.2001 27.82);
  --chart-2: oklch(56% 0.2009 270.16);
  --chart-3: oklch(43.68% 0.1557 344.85);
  --chart-4: oklch(67.12% 0.2002 345.11);
  --chart-5: oklch(57.31% 0.2001 329.91);
}

:root.dark, .dark {
  --background: oklch(14.92% 0.0129 28.8);
  --foreground: oklch(82.33% 0.0138 28.88);
  --card: oklch(20.06% 0.0138 34.39);
  --card-foreground: oklch(82.33% 0.0138 28.88);
  --popover: oklch(20.06% 0.0138 34.39);
  --popover-foreground: oklch(82.33% 0.0138 28.88);
  --primary: oklch(60.87% 0.2345 27.93);
  --primary-foreground: oklch(15.12% 0.0328 31.25);
  --secondary: oklch(20.06% 0.0138 34.39);
  --secondary-foreground: oklch(82.33% 0.0138 28.88);
  --muted: oklch(20.06% 0.0138 34.39);
  --muted-foreground: oklch(65% 0.0147 28.91);
  --accent: oklch(20.5% 0.0659 28.21);
  --accent-foreground: oklch(82.99% 0.0946 28.05);
  --destructive: oklch(60.45% 0.1998 27.17);
  --destructive-foreground: oklch(14.76% 0.0288 26.53);
  --border: oklch(25.37% 0.0141 25.54);
  --input: oklch(48.82% 0.0146 29.95);
  --ring: oklch(51.37% 0.2099 27.91);
  --chart-1: oklch(60.41% 0.2002 27.99);
  --chart-2: oklch(59.3% 0.1999 269.91);
  --chart-3: oklch(74.25% 0.1556 344.94);
  --chart-4: oklch(51.37% 0.1998 345.31);
  --chart-5: oklch(60.85% 0.1996 330.09);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}
